27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    @Column(name = "title")
41	    private String title;
42	
43	    @Column(name = "address")
44	    @NotEmpty
45	    private String address;
46	
47	    @Column(name = "address_line1")
48	    private String addressLine1;
49	
50	    @Column(name = "address_line2")
51	    private String addressLine2;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    private String email;
64	
65	    @Column(name = "registration_date")
66	    private LocalDate registrationDate;
67	
68	    @Column(name = "birth_date")
69	    private LocalDate birthDate;
70	
71	    @Column(name = "customer_code")
72	    private String customerCode;
73	
74	    @Column(name = "household_id")
75	    private String householdId;
76	
77	    @Column(name = "namesake_count")
78	    private Integer namesakeCount;
79	
80	    @Column(name = "membership_number")
81	    private String membershipNumber;
82	
83	    @Column(name = "bulk_signup_warning")
84	    private Boolean bulkSignupWarning;
85	
86	    @Column(name = "household_size")
87	    private Integer householdSize;
88	
89	    @Column(name = "postcode")
90	    private String postcode;
91	
92	    @Column(name = "possible_duplicate_of")
93	    private Integer possibleDuplicateOf;
94	
95	    @Column(name = "deleted", nullable = false)
96	    private boolean deleted;
97	
98	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
99	    private Set<Pet> pets;
100	
101	    public String getTitle() {
102	        return this.title;
103	    }
104	
105	    public void setTitle(String title) {
106	        this.title = title;
107	    }
108	
109	    public String getAddress() {
110	        return this.address;
111	    }
112	
113	    public void setAddress(String address) {
114	        this.address = address;
115	    }
116	
117	    /**
118	     * The first line of this owner's structured postal address, or {@code null} when the owner was
119	     * created with only the flat {@link #getAddress() address}. Preferred over the flat address when
120	     * present; see {@link #getAddress()} for the composed form.
121	     */
122	    public String getAddressLine1() {
123	        return this.addressLine1;
124	    }
125	
126	    public void setAddressLine1(String addressLine1) {
127	        this.addressLine1 = addressLine1;
128	    }
129	
130	    /**
131	     * The optional second line of this owner's structured postal address, or {@code null} when none
132	     * was supplied. When present it is appended to {@link #getAddressLine1() addressLine1} in the
133	     * composed {@link #getAddress() address}.
134	     */
135	    public String getAddressLine2() {
136	        return this.addressLine2;
137	    }
138	
139	    public void setAddressLine2(String addressLine2) {
140	        this.addressLine2 = addressLine2;
141	    }
142	
143	    public String getCity() {
144	        return this.city;
145	    }
146	
147	    public void setCity(String city) {
148	        this.city = city;
149	    }
150	
151	    public String getTelephone() {
152	        return this.telephone;
153	    }
154	
155	    public void setTelephone(String telephone) {
156	        this.telephone = telephone;
157	    }
158	
159	    /**
160	     * Return this owner's stored E.164 {@link #getTelephone() telephone} formatted for human display
161	     * as the calling code, a space, then the national digits grouped in threes, e.g.
162	     * {@code "+61 412 345 678"}. See {@link TelephoneFormatter}.
163	     */
164	    @Transient
165	    public String getTelephoneDisplay() {
166	        return TelephoneFormatter.toDisplay(this.telephone);
167	    }
168	
169	    public String getEmail() {
170	        return this.email;
171	    }
172	
173	    public void setEmail(String email) {
174	        this.email = email;
175	    }
176	
177	    public LocalDate getRegistrationDate() {
178	        return this.registrationDate;
179	    }
180	
181	    public void setRegistrationDate(LocalDate registrationDate) {
182	        this.registrationDate = registrationDate;
183	    }
184	
185	    public LocalDate getBirthDate() {
186	        return this.birthDate;
187	    }
188	
189	    public void setBirthDate(LocalDate birthDate) {
190	        this.birthDate = birthDate;
191	    }
192	
193	    public String getCustomerCode() {
194	        return this.customerCode;
195	    }
196	
197	    public void setCustomerCode(String customerCode) {
198	        this.customerCode = customerCode;
199	    }
200	
201	    public String getHouseholdId() {
202	        return this.householdId;
203	    }
204	
205	    public void setHouseholdId(String householdId) {
206	        this.householdId = householdId;
207	    }
208	
209	    public Integer getNamesakeCount() {
210	        return this.namesakeCount;
211	    }
212	
213	    public void setNamesakeCount(Integer namesakeCount) {
214	        this.namesakeCount = namesakeCount;
215	    }
216	
217	    public String getMembershipNumber() {
218	        return this.membershipNumber;
219	    }
220	
221	    public void setMembershipNumber(String membershipNumber) {
222	        this.membershipNumber = membershipNumber;
223	    }
224	
225	    /**
226	     * Whether this owner was created after more than 80 owners had already been registered on the
227	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
228	     */
229	    public Boolean getBulkSignupWarning() {
230	        return this.bulkSignupWarning;
231	    }
232	
233	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
234	        this.bulkSignupWarning = bulkSignupWarning;
235	    }
236	
237	    /**
238	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
239	     * counting this owner) captured once at creation.
240	     */
241	    public Integer getHouseholdSize() {
242	        return this.householdSize;
243	    }
244	
245	    public void setHouseholdSize(Integer householdSize) {
246	        this.householdSize = householdSize;
247	    }
248	
249	    /**
250	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
251	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
252	     */
253	    public String getPostcode() {
254	        return this.postcode;
255	    }
256	
257	    public void setPostcode(String postcode) {
258	        this.postcode = postcode;
259	    }
260	
261	    /**
262	     * The id of an existing owner this owner was flagged as a possible (soft) duplicate of at
263	     * creation, or {@code null} when none. Because owners sharing a last name and postcode now form
264	     * the same household — rejected as a household duplicate unless declared via {@code sharesHousehold},
265	     * and a declared member is not a suspected duplicate — this is not populated at creation.
266	     * Captured once at creation.
267	     */
268	    public Integer getPossibleDuplicateOf() {
269	        return this.possibleDuplicateOf;
270	    }
271	
272	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
273	        this.possibleDuplicateOf = possibleDuplicateOf;
274	    }
275	
276	    /**
277	     * Whether this owner was flagged as a possible (soft) duplicate of an existing owner at creation,
278	     * i.e. whether {@link #getPossibleDuplicateOf()} is set.
279	     */
280	    @Transient
281	    public Boolean getPossibleDuplicate() {
282	        return this.possibleDuplicateOf != null;
283	    }
284	
285	    /**
286	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; deleting an owner
287	     * flags it {@code true} and retains the record rather than removing it. Duplicate and identity
288	     * checks at creation ignore owners flagged deleted.
289	     */
290	    public boolean isDeleted() {
291	        return this.deleted;
292	    }
293	
294	    public void setDeleted(boolean deleted) {
295	        this.deleted = deleted;
296	    }
297	
298	    /**
299	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
300	     */
301	    @Transient
302	    public String getDisplayName() {
303	        return this.getLastName() + ", " + this.getFirstName();
304	    }
305	
306	    /**
307	     * Return this owner's salutation as the {@link #getTitle() title} and last name separated by a
308	     * space (e.g. {@code "DR Who"}), or just the last name when no title was supplied.
309	     */
310	    @Transient
311	    public String getSalutation() {
312	        return (this.title == null || this.title.isBlank())
313	            ? this.getLastName()
314	            : this.title + " " + this.getLastName();
315	    }
316	
317	    /**
318	     * Return this owner's initials as the upper-cased first letters of the first and last
319	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
320	     */
321	    @Transient
322	    public String getInitials() {
323	        return initial(this.getFirstName()) + initial(this.getLastName());
324	    }
325	
326	    private static String initial(String name) {
327	        return Character.toUpperCase(name.charAt(0)) + ".";
328	    }
329	
330	    /** Points awarded when an email address is present. */
331	    private static final int EMAIL_POINTS = 2;
332	
333	    /** Points awarded when the owner has no namesakes ({@code namesakeCount} is 0). */
334	    private static final int NO_NAMESAKE_POINTS = 1;
335	
336	    /** Points awarded for belonging to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more. */
337	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
338	
339	    /** The household size at or above which {@link #LARGE_HOUSEHOLD_POINTS} are awarded. */
340	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
341	
342	    /** Points awarded for qualifying tenure. */
343	    private static final int TENURE_POINTS = 3;
344	
345	    /** The tenure, in days, that must be exceeded to earn {@link #TENURE_POINTS}. */
346	    private static final long MEMBERSHIP_TENURE_THRESHOLD_DAYS = 365;
347	
348	    /**
349	     * Return this owner's membership points, starting at 0: add {@value #EMAIL_POINTS} when an email
350	     * address is present; add {@value #NO_NAMESAKE_POINTS} when the owner has no namesakes
351	     * ({@code namesakeCount} is 0); add {@value #LARGE_HOUSEHOLD_POINTS} for a household of
352	     * {@value #LARGE_HOUSEHOLD_SIZE} or more; add {@value #TENURE_POINTS} for qualifying tenure
353	     * (more than {@value #MEMBERSHIP_TENURE_THRESHOLD_DAYS} days since registration).
354	     */
355	    @Transient
356	    public Integer getMembershipPoints() {
357	        int points = 0;
358	        if (hasEmail()) {
359	            points += EMAIL_POINTS;
360	        }
361	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
362	            points += NO_NAMESAKE_POINTS;
363	        }
364	        if (hasLargeHousehold()) {
365	            points += LARGE_HOUSEHOLD_POINTS;
366	        }
367	        if (hasQualifyingTenure()) {
368	            points += TENURE_POINTS;
369	        }
370	        return points;
371	    }
372	
373	    /**
374	     * Return this owner's membership level, derived from {@link #getMembershipPoints() membership
375	     * points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
376	     */
377	    @Transient
378	    public Integer getMembershipLevel() {
379	        int points = getMembershipPoints();
380	        if (points <= 1) {
381	            return 1;
382	        }
383	        if (points <= 3) {
384	            return 2;
385	        }
386	        if (points <= 5) {
387	            return 3;
388	        }
389	        return 4;
390	    }
391	
392	    /**
393	     * Whether this owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more, per the
394	     * {@code householdSize} captured at creation. Owners without a recorded household size do not
395	     * qualify.
396	     */
397	    private boolean hasLargeHousehold() {
398	        return this.householdSize != null && this.householdSize >= LARGE_HOUSEHOLD_SIZE;
399	    }
400	
401	    /**
402	     * Whether this owner's tenure exceeds {@value #MEMBERSHIP_TENURE_THRESHOLD_DAYS} days, i.e.
403	     * more than that many days have elapsed since the {@code registrationDate}. Owners without a
404	     * registration date have no measurable tenure and do not qualify.
405	     */
406	    private boolean hasQualifyingTenure() {
407	        if (this.registrationDate == null) {
408	            return false;
409	        }
410	        long tenureDays = ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
411	        return tenureDays > MEMBERSHIP_TENURE_THRESHOLD_DAYS;
412	    }
413	
414	    /** Whether this owner has a usable email address (present and not blank). */
415	    private boolean hasEmail() {
416	        return this.email != null && !this.email.isBlank();
417	    }
418	
419	    /**
420	     * Return this owner's preferred contact channel: {@code "EMAIL"} when an email address is
421	     * present, otherwise {@code "PHONE"}.
422	     */
423	    @Transient
424	    public String getContactPreference() {
425	        return hasEmail() ? "EMAIL" : "PHONE";
426	    }
427	
428	    /**
429	     * Return this owner's age band derived from the {@code birthDate} as of the
430	     * {@code registrationDate}, or {@code null} when no birth date is known.
431	     */
432	    @Transient
433	    public AgeBand getAgeBand() {
434	        if (this.birthDate == null || this.registrationDate == null) {
435	            return null;
436	        }
437	        return AgeBand.asOf(this.birthDate, this.registrationDate);
438	    }
439	
440	    /**
441	     * Return this owner's locality: the region segment of the {@code customerCode} (the leading
442	     * {@code <REGION>} of {@code <REGION>-<HASH8>}), which is fixed at creation from the postcode
443	     * (preferred, matched against the known region ranges) falling back to the city-to-region table,
444	     * or {@code "UNKNOWN"} when neither yields a region. Before the customer code is assigned the
445	     * region is resolved directly from the postcode and city.
446	     */
447	    @Transient
448	    public String getLocality() {
449	        if (this.customerCode == null) {
450	            return LocalityResolver.regionFor(this.postcode, this.city);
451	        }
452	        int separator = this.customerCode.indexOf('-');
453	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
454	    }
455	
456	    /**
457	     * Return this owner's timezone: the IANA timezone name for the owner's {@link #getLocality()
458	     * locality} via the fixed region-to-timezone table, or {@code null} when the locality has no
459	     * known timezone.
460	     */
461	    @Transient
462	    public String getTimezone() {
463	        return LocalityResolver.timezoneFor(getLocality());
464	    }
465	
466	    /**
467	     * Return this owner's check digit: the single Luhn check digit computed over the digits of the
468	     * {@code customerCode}.
469	     */
470	    @Transient
471	    public Integer getCheckDigit() {
472	        return this.customerCode == null ? null : LuhnCheckDigit.of(this.customerCode);
473	    }
474	
475	    /**
476	     * Return this owner's identity key, the single derived value all duplicate detection is based
477	     * on: the normalized telephone, email and household id joined with {@code '|'} as
478	     * {@code telephone + "|" + email + "|" + householdId}, with each absent component rendered as
479	     * the empty string. Two owners are duplicates only when their whole identity keys are equal;
480	     * because the telephone is part of the key, members of one household (same {@code householdId})
481	     * with different telephones have distinct keys and are not duplicates.
482	     */
483	    @Transient
484	    public String getIdentityKey() {
485	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
486	    }
487	
488	    private static String keyPart(String value) {
489	        return value == null ? "" : value;
490	    }
491	
492	    protected Set<Pet> getPetsInternal() {
493	        if (this.pets == null) {
494	            this.pets = new HashSet<>();
495	        }
496	        return this.pets;
497	    }
498	
499	    protected void setPetsInternal(Set<Pet> pets) {
500	        this.pets = pets;
501	    }
502	
503	    public List<Pet> getPets() {
504	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
505	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
506	        return Collections.unmodifiableList(sortedPets);
507	    }
508	
509	    public void setPets(List<Pet> pets) {
510	        this.pets = new HashSet<>(pets);
511	    }
512	
513	    public void addPet(Pet pet) {
514	        getPetsInternal().add(pet);
515	        pet.setOwner(this);
516	    }
517	
518	    /**
519	     * Return the Pet with the given name, or null if none found for this Owner.
520	     *
521	     * @param name to test
522	     * @return true if pet name is already in use
523	     */
524	    public Pet getPet(String name) {
525	        return getPet(name, false);
526	    }
527	
528	    /**
529	     * Return the Pet with the given name, or null if none found for this Owner.
530	     *
531	     * @param name to test
532	     * @return true if pet name is already in use
533	     */
534	    public Pet getPet(String name, boolean ignoreNew) {
535	        name = name.toLowerCase();
536	        for (Pet pet : getPetsInternal()) {
537	            if (!ignoreNew || !pet.isNew()) {
538	                String compName = pet.getName();
539	                compName = compName.toLowerCase();
540	                if (compName.equals(name)) {
541	                    return pet;
542	                }
543	            }
544	        }
545	        return null;
546	    }
547	
548	    public Pet getPet(Integer petId) {
549	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
550	    }
551	
552	    @Override
553	    public String toString() {
554	        return new ToStringCreator(this)
555	
556	            .append("id", this.getId())
557	            .append("new", this.isNew())
558	            .append("lastName", this.getLastName())
559	            .append("firstName", this.getFirstName())
560	            .append("address", this.address)
561	            .append("city", this.city)
562	            .append("telephone", this.telephone)
563	            .append("email", this.email)
564	            .append("registrationDate", this.registrationDate)
565	            .toString();
566	    }
567	}
